/**
 * Set the field to aggregate upon.
 *
 * @param string $field The relative path of the field to aggregate upon.
 * @return void
 */
private function setField($field)
{
    $this->props[$this->aggregationType] = [
        'field' => [
            'fieldPath' => $field
        ]
    ];
}

